const actionId = typeof lifecycleInput === "string" ? lifecycleInput : lifecycleInput.actionId;
if (actionId !== "move_action") return;

const active = await capabilities.state.read("dash_active");
if (active === true) return;

const player = bindings.player_binding;
const observation = await capabilities.objects.read(player);
const now = await capabilities.time.now();
const velocityX = observation.velocity.x;
const velocityY = observation.velocity.y;
const magnitude = Math.sqrt(velocityX * velocityX + velocityY * velocityY);
const directionX = magnitude > 0 ? velocityX / magnitude : 1;
const directionY = magnitude > 0 ? velocityY / magnitude : 0;
const dashSpeed = config.normal_movement_speed * config.dash_speed_multiplier;
const duration = config.dash_duration_ms;
const endTime = now + duration;

await capabilities.objects.writeMotion(player, {
  velocity: {
    x: directionX * dashSpeed,
    y: directionY * dashSpeed
  }
});
await capabilities.state.write("dash_active", true);
await capabilities.state.write("dash_end_time", endTime);
await capabilities.time.schedule(duration, "scheduled");

const player = bindings.player_binding;
const observation = await capabilities.objects.read(player);
const velocityX = observation.velocity.x;
const velocityY = observation.velocity.y;
const magnitude = Math.sqrt(velocityX * velocityX + velocityY * velocityY);
const directionX = magnitude > 0 ? velocityX / magnitude : 1;
const directionY = magnitude > 0 ? velocityY / magnitude : 0;

await capabilities.objects.writeMotion(player, {
  velocity: {
    x: directionX * config.normal_movement_speed,
    y: directionY * config.normal_movement_speed
  }
});
await capabilities.state.write("dash_active", false);
await capabilities.state.write("dash_end_time", 0);
